function sk1301_identity(): array {$id=['name'=>'ShahkotPK','logo'=>'','favicon'=>'','tagline'=>''];try{if(function_exists('sk1100_site_identity')){$x=sk1100_site_identity();if(is_array($x))$id=array_merge($id,$x);}else{if(function_exists('current_tenant')){$t=current_tenant()?:[];$id['name']=(string)($t['site_name']??$t['name']??$id['name']);foreach(['logo_url','logo','site_logo','brand_logo','branding_logo'] as $k)if(!$id['logo']&&!empty($t[$k]))$id['logo']=(string)$t[$k];}}foreach(['site_name','app_name'] as $k){$v=sk1301_setting($k);if($v!==''){$id['name']=$v;break;}}foreach(['site_logo_url','site_logo','logo_url','logo','brand_logo','header_logo'] as $k){$v=sk1301_setting($k);if($v!==''){$id['logo']=$v;break;}}foreach(['favicon_url','favicon'] as $k){$v=sk1301_setting($k);if($v!==''){$id['favicon']=$v;break;}}foreach(['site_tagline','tagline'] as $k){$v=sk1301_setting($k);if($v!==''){$id['tagline']=$v;break;}}}catch(Throwable $e){}return $id;}
