function sk1301_canonical_url(string $url): string {if($url==='')return $url;$parts=parse_url($url);$path=(string)($parts['path']??$url);$map=sk1301_canonical_map();if(isset($map[$path]))$path=$map[$path];$q=isset($parts['query'])&&$parts['query']!==''?'?'.$parts['query']:'';$frag=isset($parts['fragment'])&&$parts['fragment']!==''?'#'.$parts['fragment']:'';if(isset($parts['scheme']))return $url;return $path.$q.$frag;}
function sk1301_manifest_rows(string $dir): array {$out=[];if(!is_dir($dir))return $out;foreach(glob(rtrim($dir,'/').'/*.json')?:[] as $file){$raw=@file_get_contents($file);$j=is_string($raw)?json_decode($raw,true):null;if(!is_array($j)){$out[]=['_file'=>$file,'_error'=>'Invalid JSON'];continue;}$rows=isset($j['items'])&&is_array($j['items'])?$j['items']:[$j];foreach($rows as $r)if(is_array($r)){$r['_file']=$file;$out[]=$r;}}return $out;}
function sk1301_scan(): array {$root=dirname(__DIR__);$issues=[];$stats=['sidebar_items'=>0,'public_nav_items'=>0,'admin_pages'=>0,'public_pages'=>0,'custom_features'=>0];
 $side=sk1301_manifest_rows(__DIR__.'/sidebar-modules');$pub=sk1301_manifest_rows(__DIR__.'/public-nav-modules');$stats['sidebar_items']=count($side);$stats['public_nav_items']=count($pub);
 foreach([['sidebar',$side,'module_key'],['public_nav',$pub,'nav_key']] as [$kind,$rows,$keyField]){$seenKey=[];$seenUrl=[];foreach($rows as $r){if(isset($r['_error'])){$issues[]=['severity'=>'high','type'=>$kind.'.json','message'=>basename((string)$r['_file']).' has invalid JSON'];continue;}$key=trim((string)($r[$keyField]??''));$url=sk1301_canonical_url(trim((string)($r['url']??'')));if($key==='')$issues[]=['severity'=>'medium','type'=>$kind.'.key','message'=>basename((string)$r['_file']).' has a missing key'];elseif(isset($seenKey[$key])&&$seenKey[$key]!==$url)$issues[]=['severity'=>'high','type'=>$kind.'.duplicate_key','message'=>$key.' points to multiple routes'];else $seenKey[$key]=$url;if($url!==''){if(isset($seenUrl[$url])&&$seenUrl[$url]!==$key)$issues[]=['severity'=>'medium','type'=>$kind.'.duplicate_url','message'=>$url.' is registered by more than one key'];else $seenUrl[$url]=$key;}}}
 foreach(sk1301_canonical_map() as $old=>$new){foreach($side as $r)if((string)($r['url']??'')===$old)$issues[]=['severity'=>'medium','type'=>'route.alias','message'=>'Admin manifest still uses '.$old.' instead of '.$new];foreach($pub as $r)if((string)($r['url']??'')===$old)$issues[]=['severity'=>'medium','type'=>'route.alias','message'=>'Public manifest still uses '.$old.' instead of '.$new];}
 $adminDir=$root.'/admin';if(is_dir($adminDir))foreach(glob($adminDir.'/*.php')?:[] as $f){$stats['admin_pages']++;$txt=(string)@file_get_contents($f);if(strlen($txt)>0&&!str_contains($txt,'layout.php')&&!str_contains($txt,'admin_sidebar_global_v974'))$issues[]=['severity'=>'low','type'=>'admin.shell','message'=>basename($f).' does not reference the shared admin shell directly'];}
 foreach(glob($root.'/*.php')?:[] as $f){$stats['public_pages']++;$bn=basename($f);if(preg_match('/-v\d+\.php$/i',$bn)){$clean=preg_replace('/-v\d+(?:\d+)?\.php$/i','.php',$bn);if($clean&&is_file($root.'/'.$clean))$issues[]=['severity'=>'low','type'=>'route.versioned','message'=>$bn.' has a clean-route sibling '.$clean];}}
 if(sk1301_table('access_tenant_custom_features_v1301'))try{$q=sk1301_db()->prepare('SELECT COUNT(*) FROM access_tenant_custom_features_v1301 WHERE tenant_id=? AND active=1');$q->execute([sk1301_tid()]);$stats['custom_features']=(int)$q->fetchColumn();}catch(Throwable $e){}
 if(sk1301_table('tenant_members')&&sk1301_table('users'))try{$uc=sk1301_cols('users');$tc=sk1301_cols('tenant_members');$ur=isset($uc['role_key'])?'u.role_key':(isset($uc['role'])?'u.role':"''");$mr=isset($tc['member_role'])?'tm.member_role':(isset($tc['role_key'])?'tm.role_key':(isset($tc['role'])?'tm.role':"''"));$q=sk1301_db()->query("SELECT COUNT(*) FROM users u JOIN tenant_members tm ON tm.user_id=u.id WHERE LOWER(COALESCE($ur,'')) IN ('seller','shopkeeper','merchant','vendor','customer','member','client') AND LOWER(COALESCE($mr,'')) IN ('admin','administrator','manager','tenant_admin')");$n=(int)$q->fetchColumn();if($n>0)$issues[]=['severity'=>'high','type'=>'access.legacy_role','message'=>$n.' customer/shopkeeper tenant memberships still have staff-like roles'];}catch(Throwable $e){}
 $score=max(0,100-(count(array_filter($issues,fn($x)=>$x['severity']==='high'))*15+count(array_filter($issues,fn($x)=>$x['severity']==='medium'))*7+count(array_filter($issues,fn($x)=>$x['severity']==='low'))*2));return ['score'=>$score,'issues'=>$issues,'stats'=>$stats,'identity'=>sk1301_identity(),'theme'=>sk1301_theme(),'version'=>'13.0.1'];}
